all{font-size:10px}.empty{padding:18px;text-align:center;opacity:.6;font-size:13px}#error:empty{display:none}.toolbar{position:sticky;top:0;background:Canvas;padding:10px 0;z-index:1}code{font-family:ui-monospace,monospace;font-size:11px;overflow-wrap:anywhere}@media(max-width:340px){main{padding:12px}h1{font-size:18px}.card{padding:11px}}\n\nheader>button,header>.pill{flex-shrink:0}header>div{min-width:0}.row>button,header>button{white-space:nowrap}.item{white-space:normal}\n.item .grow{white-space:normal;overflow-wrap:anywhere}\n\n.primary:hover{background:var(--kudium-primary);filter:brightness(1.08)}\n\n.panel-navigator{padding:20px 16px;max-width:760px;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif}.panel-navigator header{margin-bottom:18px;align-items:center}.panel-navigator .eyebrow{font-size:11px;letter-spacing:0;text-transform:none;opacity:.5}.panel-navigator h1{font-size:19px;font-weight:650;line-height:1.35;letter-spacing:-.4px;margin:8px 0}.panel-navigator .muted{font-size:11px}.panel-navigator #branch{overflow-wrap:anywhere;font-size:10px}.panel-navigator svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round;flex-shrink:0}.panel-navigator .icon-button{width:32px;height:32px;flex-shrink:0;padding:7px;display:grid;place-items:center;background:transparent;border-radius:50%;opacity:.6}.panel-navigator .icon-button:hover{background:color-mix(in srgb,CanvasText 7%,Canvas);opacity:1}.panel-navigator .stats{gap:14px;margin:14px 0 18px}.panel-navigator .stats>div{display:flex;gap:5px;align-items:baseline}.panel-navigator .stats strong{font-size:13px;font-weight:650}.panel-navigator .stats small{font-size:10px;text-transform:none}.panel-navigator .toolbar{padding:8px 0 12px;background:Canvas;z-index:1}.search-field{position:relative}.search-field>svg{position:absolute;left:10px;top:11px;width:15px;height:15px;opacity:.45;pointer-events:none}.panel-navigator input[type=search]{padding:10px 12px 10px 33px;font-size:12px;background:color-mix(in srgb,CanvasText 5%,Canvas);border-radius:10px}.panel-navigator select{font-size:11px;padding:8px;background:color-mix(in srgb,CanvasText 5%,Canvas);border-radius:8px}.filter-row{display:flex;align-items:center;gap:10px;margin-top:10px}.filter-row select{width:auto;max-width:60%;flex:1}.filter-row a{margin-left:auto;font-size:10px;white-space:nowrap;display:flex;gap:3px;align-items:center}.filter-row a svg{width:13px;height:13px}.panel-navigator .list{gap:2px}.panel-navigator .item{background:transparent;padding:11px 8px;border-radius:9px;display:flex;align-items:center;gap:8px}.panel-navigator .item:hover{background:color-mix(in srgb,CanvasText 4%,Canvas);text-decoration:none}.panel-navigator .item strong{font-size:12px;font-weight:500;line-height:1.5}.panel-navigator .item small{font-size:10px;margin-top:3px;line-height:1.45}.panel-navigator .file-icon{opacity:.35;width:16px;height:16px;align-self:flex-start;margin-top:3px}.panel-navigator .check-button{background:transparent;padding:6px;width:30px;height:30px;flex-shrink:0;border-radius:50%;opacity:.5;display:grid;place-items:center}.panel-navigator .check-button[aria-pressed=true]{background:color-mix(in srgb,var(--kudium-primary) 14%,Canvas);color:var(--kudium-primary);opacity:1}.panel-navigator .check-button:hover{opacity:1}.panel-navigator .segments{display:flex;gap:3px;padding:3px;border-radius:9px;background:color-mix(in srgb,CanvasText 5%,Canvas);margin-top:10px}.panel-navigator .segments button{flex:1;background:transparent;font-size:11px;padding:7px 8px;border-radius:7px;opacity:.6;white-space:nowrap}.panel-navigator .segments button[aria-pressed=true]{background:color-mix(in srgb,CanvasText 10%,Canvas);color:inherit;opacity:1;filter:none;font-weight:550}.panel-navigator #link-filter{width:100%;margin-top:8px}.panel-navigator #notice,.panel-navigator #summary{font-size:10px;margin:2px 0 9px;opacity:.5}.panel-navigator .source-arrow{opacity:.35;width:14px;height:14px;margin-left:auto}.panel-navigator details{margin-top:12px}.panel-navigator summary{font-size:11px;cursor:pointer;opacity:.65;padding:8px 0}.panel-navigator details p{font-size:11px;line-height:1.65}.panel-navigator .local-note{font-size:10px;opacity:.45;margin:18px 0 0}.panel-navigator #description{white-space:pre-wrap}.panel-navigator #threads .item{display:block;font-size:11px;line-height:1.6}@media(max-width:340px){.panel-navigator{padding:16px 12px}.panel-navigator h1{font-size:18px}.panel-navigator .stats{gap:10px}}\n","script":"let prData;\nconst el=id=>document.getElementById(id);\nasync function action(id,payload){el('error').textContent='';try{await kudiumHookPanel.invoke(id,payload);}catch(error){el('error').textContent=error.message;}}\nfunction renderFiles(){if(!prData)return;const query=el('search').value.toLowerCase(),filter=el('filter').value;\n  const list=prData.files.filter(file=>file.path.toLowerCase().includes(query)&&(filter!=='todo'||!file.reviewed)&&(filter!=='test'||file.test));\n  el('files').replaceChildren(...list.map(file=>{\n    const row=document.createElement('div');row.className='item row';\n    const jump=document.createElement('button');jump.className='grow';jump.style.cssText='background:none;padding:0;text-align:left';\n    const name=document.createElement('strong');name.textContent=file.path.split('/').pop();jump.title=file.path;const detail=document.createElement('small');detail.textContent=file.folder+(file.test?' · test':'')+(file.additions||file.deletions?' · +'+file.additions+' −'+file.deletions:'');jump.append(name,detail);jump.onclick=()=>action('pr-jump',{index:file.index});\n    const check=document.createElement('button');check.className='check-button';check.innerHTML='<svg viewBox=\"0 0 24 24\">'+(file.reviewed?'<path d=\"m5 12 4 4 10-10\"/>':'<circle cx=\"12\" cy=\"12\" r=\"8\"/>')+'</svg>'; check.setAttribute('aria-label',(file.reviewed?'Uncheck ':'Mark checked ')+file.path);check.setAttribute('aria-pressed',String(file.reviewed));check.onclick=()=>action('pr-check',{index:file.index});const icon=document.createElementNS('http://www.w3.org/2000/svg','svg');icon.setAttribute('viewBox','0 0 24 24');icon.classList.add('file-icon');icon.setAttribute('aria-hidden','true');icon.innerHTML='<path d=\"M14 3H6v18h12V7zM14 3v5h4\"/>';row.append(icon,jump,check);return row;\n  }));if(!list.length){const empty=document.createElement('p');empty.className='empty';empty.textContent=prData.files.length?'No files match this filter.':'Open Files changed, then Refresh to build your review map.';el('files').append(empty);}\n}\nel('search').oninput=renderFiles;el('filter').onchange=renderFiles;el('refresh').onclick=()=>action('pr-refresh');\nkudiumHookPanel.onUpdate(output=>{prData=output.content.data;el('title').textContent=prData.title;el('branch').textContent=prData.branch?'Branch · '+prData.branch:'';el('loaded').textContent=prData.files.length;el('checked').textContent=prData.files.filter(file=>file.reviewed).length;el('tests').textContent=prData.files.filter(file=>file.test).length;el('files-link').href=prData.url+'/files';el('notice').textContent='Showing '+prData.files.length+' loaded files'+(prData.total>prData.files.length?' of '+prData.total+' reported by GitHub':'')+'.';el('description').textContent=prData.description||'Open the conversation tab, then refresh to read the description.';el('threads-title').textContent=prData.comments.length+' loaded review threads';el('threads').replaceChildren(...prData.comments.map(text=>{const p=document.createElement('p');p.className='item';p.textContent=text;return p;}));renderFiles();});\n"};
if (!/^\/[^/]+\/[^/]+\/pull\/\d+(?:\/|$)/.test(location.pathname)) return;
let prNodes = [], prReviewed = new Set(), prIdentity = location.pathname.match(/^\/[^/]+\/[^/]+\/pull\/\d+/)[0];
const storageKey = 'kudium-pr-notes:' + prIdentity;
try { prReviewed = new Set(JSON.parse(sessionStorage.getItem(storageKey)||'[]').filter(path => typeof path === 'string')); } catch {}
const scanPR = () => {
  const roots = [...document.querySelectorAll('.file[data-path], [data-file-path]')];
  const deduped = new Map();
  for (const root of roots) {
    const path = root.getAttribute('data-path') || root.getAttribute('data-file-path');
    if (!path || deduped.has(path)) continue;
    deduped.set(path,{node:root,path});
  }
  prNodes = [...deduped.values()].slice(0,150);
  const files = prNodes.map(({node,path},index) => ({ index,path:path.slice(0,500),folder:path.includes('/')?path.slice(0,path.lastIndexOf('/')).slice(0,180):'Root',
    additions:Number(node.querySelector('.diffstat .color-fg-success')?.textContent?.replace(/\D/g,'')) || 0,
    deletions:Number(node.querySelector('.diffstat .color-fg-danger')?.textContent?.replace(/\D/g,'')) || 0,
    reviewed:prReviewed.has(path), test:/test|spec|__tests__/i.test(path) }));
  while (JSON.stringify(files).length > 40000) { files.pop(); prNodes.pop(); }
  const comments = [...document.querySelectorAll('.review-thread, .js-resolvable-timeline-thread-container')].slice(0,40).map(node => node.innerText.trim().slice(0,420)).filter(Boolean);
  const description = document.querySelector('.js-comment-body, [data-testid="issue-body"]')?.innerText?.trim().slice(0,1800) || '';
  const filesTab = document.querySelector('#files_tab_counter, [data-content="Files changed"] .Counter');
  return { title:document.querySelector('.js-issue-title, [data-testid="issue-title"]')?.textContent?.trim().slice(0,180) || document.title.split('·')[0].trim().slice(0,180),
    url:location.origin+prIdentity, branch:document.querySelector('.head-ref')?.textContent?.trim().slice(0,160) || '', files, comments, description,
    total:Number(filesTab?.textContent?.replace(/\D/g,'')) || files.length };
};
const publishPR = async () => context.panel.update({id:'pr',title:'PR review navigator',content:{type:'html',...panelDesign,data:scanPR()},actions:prActions});
const prActions = [{id:'pr-refresh',label:'Refresh'},{id:'pr-jump',label:'Jump to file'},{id:'pr-check',label:'Mark checked'}];
context.panel.onAction('pr-refresh',async()=>{await publishPR();return {refreshed:true};});
context.panel.onAction('pr-jump',async payload=>{
  const entry=prNodes[Number(payload?.index)]; if (!entry || !Number.isInteger(payload?.index)) throw new Error('Refresh the file list first.');
  entry.node.scrollIntoView({behavior:'auto',block:'start'}); return {path:entry.path};
});
context.panel.onAction('pr-check',async payload=>{
  const entry=prNodes[Number(payload?.index)]; if (!entry || !Number.isInteger(payload?.index)) throw new Error('Refresh the file list first.');
  prReviewed.has(entry.path)?prReviewed.delete(entry.path):prReviewed.add(entry.path);
  try { sessionStorage.setItem(storageKey,JSON.stringify([...prReviewed].slice(0,1000))); } catch {}
  await publishPR(); return {checked:prReviewed.has(entry.path)};
});
await context.panel.show({id:'pr',title:'PR review navigator',reveal:false,content:{type:'html',...panelDesign,data:scanPR()},actions:prActions});
